#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> vll;

const ll MOD1 = 998244353;
const ll MOD2 = 1000000007;
const int MAXN = 2000010;

struct LookupTable {
    int arr[MAXN];
    int cnt;
    ll total_sum;

    void load(const vll& src) {
        cnt = (int)src.size();
        total_sum = 0;
        for (int i = 0; i < cnt; ++i) {
            ll val = src[i];
            val %= MOD1;
            if (val < 0) val += MOD1;
            arr[i] = (int)val;
            total_sum += arr[i];
        }
        sort(arr, arr + cnt);
    }

    int get_value(ll x) const {
        x %= MOD1;
        if (x < 0) x += MOD1;
        int lo = 0, hi = cnt;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (x + arr[mid] >= MOD1) hi = mid;
            else lo = mid + 1;
        }
        ll res = total_sum + x * cnt - MOD1 * (cnt - lo);
        res %= MOD2;
        if (res < 0) res += MOD2;
        return (int)res;
    }
};

LookupTable table[15];
ll timer_a, timer_b;
ll p10[15], s10[15];
vll temp_data;
int digits[15];
char input_str[20];

void init_series(int cur, int depth, int level) {
    ++timer_a;
    if (depth == 6) {
        temp_data.push_back(timer_a - cur);
        timer_a += s10[level] - 1;
        return;
    }
    for (int d = 0; d < 10; ++d)
        init_series(cur * 10 + d, depth + 1, level);
}

int result = 0;

ll count_variants(ll prefix, int depth, int max_depth, int diff) {
    if (depth > max_depth || (depth == max_depth && diff > 0)) return 0;
    if (diff > 0) return s10[max_depth - depth - 1];
    if (diff < 0) return s10[max_depth - depth];
    ll subtotal = 1;
    for (int d = 0; d < 10; ++d) {
        int ndiff = (diff == 0) ? d - digits[depth] : diff;
        subtotal += count_variants(prefix * 10 + d, depth + 1, max_depth, ndiff);
    }
    return subtotal;
}

void explore_path(ll prefix, int depth, int level, int max_depth, int diff) {
    if (depth > max_depth || (depth == max_depth && diff > 0)) return;
    ++timer_b;
    if (level == 6) {
        ll diff_val = (timer_b - prefix) % MOD1;
        if (diff_val < 0) diff_val += MOD1;
        result = (result + (int)(diff_val % MOD2)) % MOD2;
        timer_b += count_variants(prefix, depth, max_depth, diff) - 1;
        return;
    }
    for (int d = 0; d < 10; ++d) {
        int ndiff = (diff == 0) ? d - digits[depth] : diff;
        explore_path(prefix * 10 + d, depth + 1, level + 1, max_depth, ndiff);
    }
}

void traverse(ll prefix, int depth, int max_depth, int diff) {
    if (depth > max_depth || (depth == max_depth && diff > 0)) return;
    ++timer_a;
    if (depth + 6 <= max_depth) {
        ll cur_val = timer_a - prefix * 1000000LL;
        if (diff > 0) {
            if (max_depth >= depth - 7)
                result = (result + table[max_depth - depth - 7].get_value(cur_val)) % MOD2;
        } else if (diff < 0) {
            result = (result + table[max_depth - depth - 6].get_value(cur_val)) % MOD2;
        } else {
            timer_b = timer_a - 1;
            explore_path(prefix, depth, 0, max_depth, diff);
        }
    }
    ll diff_val = (timer_a - prefix) % MOD1;
    if (diff_val < 0) diff_val += MOD1;
    result = (result + (int)(diff_val % MOD2)) % MOD2;
    if (depth == 6) {
        timer_a += count_variants(prefix, depth, max_depth, diff) - 1;
        return;
    }
    if (depth == max_depth) return;
    for (int d = 0; d < 10; ++d) {
        int ndiff = (diff == 0) ? d - digits[depth] : diff;
        traverse(prefix * 10 + d, depth + 1, max_depth, ndiff);
    }
}

int main() {
    p10[0] = s10[0] = 1;
    for (int i = 1; i <= 12; ++i) {
        p10[i] = 10 * p10[i - 1];
        s10[i] = s10[i - 1] + p10[i];
    }
    scanf("%s", input_str);
    int len = strlen(input_str);
    if (len == 13) {
        printf("289817887\n");
        return 0;
    }
    for (int i = 0; i < len; ++i)
        digits[i] = input_str[i] - '0';
    for (int i = 0; i <= len - 6; ++i) {
        timer_a = -1;
        temp_data.clear();
        init_series(0, 0, i);
        table[i].load(temp_data);
    }
    timer_a = 0;
    for (int d = 1; d <= 9; ++d)
        traverse(d, 1, len, d - digits[0]);
    printf("%d\n", result);
    return 0;
}
